<?php
declare(strict_types=1);

date_default_timezone_set('America/New_York');

$installerName = 'install_standings_timeline_manual_support_v007_20261110_124003pm.php';
$expectedSha = '77413dd2e3f263a0b6d03096008786b0ffff6ebe6078490ba8c10574e03eb43c';
$payload = '';

function lh($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function lj(array $v): string { return (string)json_encode($v, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES); }
function lcheck(array &$c, string $l, bool $ok, bool $r, string $d = ''): void {
    $c[] = ['label'=>$l,'status'=>$ok?'PASS':'FAIL','required'=>$r,'detail'=>$d];
}

$checks = [];

$okDir = (basename(__DIR__) === '_installers' && basename(dirname(__DIR__)) === 'public_html');
lcheck($checks, 'LINTGATE running from /public_html/_installers', $okDir, true, __DIR__);

$decoded = base64_decode($payload, true);
$decodedOk = is_string($decoded) && $decoded !== '';
lcheck($checks, 'Embedded installer decoded', $decodedOk, true, $decodedOk ? strlen($decoded) . ' bytes' : 'decode failed');

$actualSha = $decodedOk ? hash('sha256', $decoded) : '';
lcheck($checks, 'Embedded installer SHA-256 verified', $actualSha === $expectedSha, true, $actualSha);

$staged = __DIR__ . '/' . $installerName;
$stagedOk = false;

if ($decodedOk && $actualSha === $expectedSha && $okDir) {
    $tmp = $staged . '.tmp_' . getmypid() . '_' . date('Ymd_His');
    if (file_put_contents($tmp, $decoded, LOCK_EX) !== false) {
        @chmod($tmp, 0644);
        if (@rename($tmp, $staged)) {
            @chmod($staged, 0644);
            $stagedOk = true;
        } else {
            @unlink($tmp);
        }
    }
}

lcheck($checks, 'Real installer staged', $stagedOk && is_file($staged), true, $staged);

$lintOut = '';
$lintOk = false;
if ($stagedOk && is_file($staged)) {
    $o = shell_exec('php -l ' . escapeshellarg($staged) . ' 2>&1');
    $lintOut = is_string($o) ? trim($o) : '';
    $lintOk = strpos($lintOut, 'No syntax errors detected') !== false;
}
lcheck($checks, 'Real installer php -l', $lintOk, true, $lintOut);

$ok = true;
foreach ($checks as $c) {
    if ($c['required'] && $c['status'] !== 'PASS') {
        $ok = false;
        break;
    }
}

$report = [
    'lintgate' => 'standings_timeline_manual_support_v007',
    'report_stage' => 'LINTGATE',
    'generated_at_et' => date('c'),
    'scope' => [
        'target' => 'race_results/standings_timeline.php',
        'purpose' => 'Teach Timeline Lite/full timeline to reconstruct manual scoring releases correctly without altering the ESPN canonical chain.',
    ],
    'result' => [
        'ok' => $ok,
        'checks' => $checks,
        'real_installer' => $staged,
        'expected_sha256' => $expectedSha,
    ],
];

$status = $ok ? 'PASS' : 'FAIL';
?>
<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>MRL Timeline Manual Support v007 LINTGATE</title>
<style>
body{margin:0;background:#0f0f0f;color:#eee;font:18px Arial;padding:28px}
