.box{border:1px solid #444;background:#191919;padding:18px;border-radius:12px;margin:14px 0}
.pass{color:#65eb94}.fail{color:#ff7777}
a{color:#5da9ff}
button{border:1px solid #777;border-radius:9px;padding:10px 18px;color:#fff;background:#555;font-size:18px;cursor:pointer}
pre{white-space:pre-wrap;background:#050505;border:1px solid #444;padding:14px;max-height:580px;overflow:auto;font-size:13px}
</style>
</head>
<body>
<h1>MRL Timeline Manual Support v007 LINTGATE</h1>
<div class="box">
  <h2 class="<?php echo $status === 'PASS' ? 'pass' : 'fail'; ?>">STATUS: <?php echo lh($status); ?></h2>
  <?php if($ok): ?>
  <p>Real installer staged:
    <a href="<?php echo lh($installerName); ?>"><?php echo lh($installerName); ?></a>
  </p>
  <?php endif; ?>
</div>
<div class="box">
  <button type="button" onclick="navigator.clipboard.writeText(document.getElementById('rep').innerText)">Copy Report</button>
  <pre id="rep"><?php echo lh(lj($report)); ?></pre>
</div>
</body>
